                          </thead>
                          <tbody className="divide-y divide-white/[0.08]/60">
                            {referrals.map((r) => {
                              const cleanDigits = (r.friendPhone || "").replace(/\D/g, "");
                              const waUrl = cleanDigits.length >= 10 ? `https://api.whatsapp.com/send?phone=91${cleanDigits.slice(-10)}` : null;

