                              </div>
                              <div className="h-2 w-full bg-[#11131A] border border-white/[0.08]">
                                <div className="h-full bg-[#00FF66] transition-all duration-300" style={{ width: `${pct}%` }} />
                              </div>
                            </div>
                          </div>

                          <div className="pt-2">
                            {isClaimed ? (
                              <div className="w-full py-2 bg-[#00FF66]/15 border border-[#00FF66]/40 text-[#00FF66] text-xs font-bold uppercase text-center flex items-center justify-center gap-1.5">
