                                Claim {m.title} Now
                              </button>
                            ) : (
                              <button
                                type="button"
                                disabled
                                className="w-full py-2 bg-[#11131A] border border-white/[0.08] text-[#8E929B] text-xs font-bold uppercase tracking-wider opacity-60 cursor-not-allowed"
