                            required
                            value={claimAddress.recipientName}
                            onChange={(e) => setClaimAddress({ ...claimAddress, recipientName: e.target.value })}
                            className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-2 text-white focus:outline-none focus:border-white"
                          />
                        </div>

                        <div>
                          <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">Contact Phone</label>
                          <input
                            type="tel"
                            required
                            value={claimAddress.phone}
                            onChange={(e) => setClaimAddress({ ...claimAddress, phone: e.target.value })}
                            className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-2 text-white focus:outline-none focus:border-white"
                          />
                        </div>

                        <div>
                          <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">Delivery Address</label>
                          <input
                            type="text"
                            required
                            placeholder="Flat/House No., Street, Landmark"
                            value={claimAddress.address}
                            onChange={(e) => setClaimAddress({ ...claimAddress, address: e.target.value })}
                            className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-2 text-white focus:outline-none focus:border-white"
                          />
                        </div>

                        <div className="grid grid-cols-3 gap-2">
                          <div>
                            <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">City</label>
                            <input
                              type="text"
                              required
                              value={claimAddress.city}
                              onChange={(e) => setClaimAddress({ ...claimAddress, city: e.target.value })}
                              className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-2 text-white focus:outline-none focus:border-white"
                            />
                          </div>
                          <div>
                            <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">State</label>
                            <input
                              type="text"
                              required
                              value={claimAddress.state}
                              onChange={(e) => setClaimAddress({ ...claimAddress, state: e.target.value })}
                              className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-2 text-white focus:outline-none focus:border-white"
                            />
                          </div>
                          <div>
                            <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">Pincode</label>
                            <input
                              type="text"
                              required
                              maxLength={6}
                              value={claimAddress.pincode}
                              onChange={(e) => setClaimAddress({ ...claimAddress, pincode: e.target.value })}
                              className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-2 text-white focus:outline-none focus:border-white"
                            />
                          </div>
                        </div>

                        <div className="pt-2 flex items-center justify-end gap-2">
                          <button
                            type="button"
                            onClick={() => setClaimingMilestone(null)}
                            className="px-3 py-2 border border-white/[0.08] text-[#8E929B] hover:text-white uppercase font-bold text-xs"
                          >
                            Cancel
                          </button>
                          <button
                            type="submit"
                            disabled={isSubmittingClaim}
                            className="px-4 py-2 bg-[#00FF66] text-black font-bold uppercase text-xs hover:bg-[#00E65C] transition-colors disabled:opacity-50 flex items-center gap-1.5"
                          >
                            {isSubmittingClaim && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
                            <span>Confirm &amp; Dispatch Gift</span>
                          </button>
                        </div>
                      </form>
                    </div>
                  </div>
                )}
              </div>
            );
          })()}

          {/* ---------------- NOTIFICATIONS TAB ---------------- */}
          {activeTab === "notifications" && (
            <div className="space-y-6">
              <div className="border-b border-white/[0.08] pb-3 flex flex-wrap items-end justify-between gap-3">
                <div>
                  <h1 className="text-lg sm:text-xl font-bold uppercase text-white tracking-tight" style={{ fontFamily: "var(--font-space-grotesk), sans-serif" }}>
                    Alerts &amp; Updates
                  </h1>
                </div>
                {unreadCount > 0 && (
                  <button
                    type="button"
                    onClick={handleMarkAllRead}
                    disabled={markingAllRead}
                    className="inline-flex items-center gap-1.5 px-3 py-2 border border-white/[0.08] bg-[#11131A] hover:border-white disabled:opacity-60 text-[10px] font-bold uppercase tracking-wider text-white transition-colors"
                  >
                    {markingAllRead ? <Loader2 className="w-3 h-3 animate-spin" /> : <Check className="w-3 h-3" />}
                    Mark all as read
                  </button>
                )}
              </div>

              {notifications.length === 0 ? (
                <div className="border border-white/[0.08] bg-[#11131A] p-12 text-center text-[#8E929B]">
                  <Bell className="w-8 h-8 mx-auto mb-2 text-[#8E929B]" />
                  <p className="text-xs uppercase font-bold">No notifications right now</p>
                </div>
              ) : (
                <div className="space-y-2">
                  {notifications.map((n) => (
                    <div
                      key={n.id}
                      className={`border p-4 flex items-start gap-3 transition-colors ${
                        n.read
                          ? "border-white/[0.06] bg-[#0D0F14] opacity-70"
                          : "border-white/[0.08] bg-[#11131A]"
                      }`}
                    >
                      <span className={`mt-1.5 w-1.5 h-1.5 rounded-full shrink-0 ${n.read ? "bg-[#3A3E48]" : "bg-[#D9362B]"}`} />
                      <div className="flex-1 min-w-0 text-xs">
                        <p className={`font-bold ${n.read ? "text-[#C6CAD3]" : "text-white"}`}>{n.title}</p>
                        <p className="text-[#A5AAB8] mt-0.5">{n.message}</p>
                        <span className="text-[10px] text-[#8E929B] block mt-1">{dateTimeLabel(n.createdAt)}</span>
                      </div>
                      {!n.read && (
                        <button
                          type="button"
                          onClick={() => handleMarkRead(n.id)}
                          disabled={markingNotificationId === n.id}
                          className="shrink-0 inline-flex items-center gap-1 text-[10px] font-bold uppercase text-[#8E929B] hover:text-white disabled:opacity-60 transition-colors"
                        >
                          {markingNotificationId === n.id ? (
                            <Loader2 className="w-3 h-3 animate-spin" />
                          ) : (
                            <Check className="w-3 h-3" />
                          )}
                          Read
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* ---------------- PROFILE TAB ---------------- */}
          {activeTab === "profile" && (
            <div className="space-y-6">
              <div className="border-b border-white/[0.08] pb-3">
                <h1 className="text-lg sm:text-xl font-bold uppercase text-white tracking-tight" style={{ fontFamily: "var(--font-space-grotesk), sans-serif" }}>
                  Profile &amp; Addresses
                </h1>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="border border-white/[0.08] bg-[#11131A] p-5 space-y-4">
                  <div className="flex items-center justify-between">
                    <h3 className="text-xs font-bold uppercase text-white font-sans">Contact Details</h3>
                    {!isEditingProfile && (
                      <button
                        type="button"
                        onClick={startEditingProfile}
                        className="text-[10px] uppercase font-bold text-[#D9362B] hover:text-white px-2 py-0.5 border border-white/[0.08] hover:border-white transition-colors"
                      >
                        Edit Details
                      </button>
                    )}
                  </div>

                  {profileSuccess && (
                    <p className="text-xs text-[#00FF66] font-medium">{profileSuccess}</p>
                  )}
                  {profileError && (
                    <p className="text-xs text-[#D9362B] font-medium">{profileError}</p>
                  )}

                  {isEditingProfile ? (
                    <form onSubmit={handleSaveProfile} className="space-y-3 pt-1">
                      <div>
                        <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">Full Name</label>
                        <input
                          type="text"
                          required
                          value={profileName}
                          onChange={(e) => setProfileName(e.target.value)}
                          placeholder="Your Name"
                          className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-1.5 text-xs text-white focus:outline-none focus:border-white"
                        />
                      </div>
                      <div>
                        <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">Phone Number</label>
                        <input
                          type="tel"
                          value={profilePhone}
                          onChange={(e) => setProfilePhone(e.target.value)}
                          placeholder="+91 98765 43210"
                          className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-1.5 text-xs text-white focus:outline-none focus:border-white"
                        />
                      </div>
                      <div>
                        <label className="text-[10px] uppercase font-bold text-[#8E929B] block mb-1">Email Address</label>
                        <input
                          type="email"
                          value={profileEmail}
                          onChange={(e) => setProfileEmail(e.target.value)}
                          placeholder="you@example.com"
                          className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-1.5 text-xs text-white focus:outline-none focus:border-white"
                        />
                      </div>
                      <div className="flex items-center gap-2 pt-1">
                        <button
                          type="submit"
                          disabled={profileSaving}
                          className="px-3 py-1.5 bg-[#D9362B] hover:bg-[#B82B22] text-white text-xs font-bold uppercase transition-colors disabled:opacity-50 flex items-center gap-1.5"
                        >
                          {profileSaving && <Loader2 className="w-3 h-3 animate-spin" />}
                          <span>Save Changes</span>
                        </button>
                        <button
                          type="button"
                          onClick={() => setIsEditingProfile(false)}
                          className="px-3 py-1.5 border border-white/[0.08] text-[#8E929B] hover:text-white text-xs font-bold uppercase transition-colors"
                        >
                          Cancel
                        </button>
                      </div>
                    </form>
                  ) : (
                    <div className="space-y-2 text-xs">
                      <div>
                        <span className="text-[10px] text-[#8E929B] uppercase block">Full Name</span>
                        <span className="text-white font-bold">{customer.name || "Skywear Collector"}</span>
                      </div>
                      <div>
                        <span className="text-[10px] text-[#8E929B] uppercase block">Phone</span>
                        <span className="text-white font-bold">{customer.phone || "Not linked"}</span>
                      </div>
                      <div>
                        <span className="text-[10px] text-[#8E929B] uppercase block">Email</span>
                        <span className="text-white font-bold">{customer.email || "Not linked"}</span>
                      </div>
                    </div>
                  )}
                </div>

                <div className="border border-white/[0.08] bg-[#11131A] p-5 space-y-4">
                  <h3 className="text-xs font-bold uppercase text-white font-sans">Default Delivery Address</h3>
                  {customer.addresses && customer.addresses.length > 0 ? (
                    <div className="space-y-1 text-xs text-[#A5AAB8]">
                      <p className="text-white font-bold">{customer.addresses[0].street}</p>
                      <p>{customer.addresses[0].city}, {customer.addresses[0].state} - {customer.addresses[0].pincode}</p>
                    </div>
                  ) : (
                    <p className="text-xs text-[#8E929B]">No address saved yet.</p>
                  )}
                </div>

                {/* Password & Security Card */}
                <div className="border border-white/[0.08] bg-[#11131A] p-5 space-y-4 sm:col-span-2">
                  <div className="flex items-center gap-2">
                    <KeyRound className="w-4 h-4 text-[#00FF66]" />
                    <h3 className="text-xs font-bold uppercase text-white font-sans">Account Password & Security</h3>
                  </div>

                  <p className="text-xs text-[#8E929B]">
                    {customer.password
                      ? "You can update your login password below. You will still be able to log in via WhatsApp OTP anytime."
                      : "You currently log in via WhatsApp OTP. Set a password below so you can also log in directly without OTP."}
                  </p>

                  <form onSubmit={handleUpdatePassword} className="space-y-3 max-w-md">
                    <div>
                      <label className="text-[10px] uppercase font-bold text-[#A5AAB8] block mb-1">
                        {customer.password ? "New Password" : "Create Password"}
                      </label>
                      <input
                        type="password"
                        placeholder="At least 6 characters"
                        value={profileNewPass}
                        onChange={(e) => setProfileNewPass(e.target.value)}
                        className="w-full bg-[#0A0B0E] border border-white/[0.08] px-3 py-2 text-xs text-white focus:outline-none focus:border-white transition-colors"
                      />
                    </div>

                    {profilePassError && (
                      <p className="text-xs text-[#D9362B] font-medium">{profilePassError}</p>
                    )}
                    {profilePassSuccess && (
                      <p className="text-xs text-[#00FF66] font-medium">{profilePassSuccess}</p>
                    )}

                    <button
                      type="submit"
                      disabled={profilePassLoading || !profileNewPass}
                      className="px-4 py-2 bg-white text-black hover:bg-neutral-200 disabled:opacity-50 text-xs font-bold uppercase transition-colors flex items-center gap-2"
                    >
                      {profilePassLoading && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
                      <span>{customer.password ? "Update Password" : "Save Password"}</span>
                    </button>
                  </form>
                </div>
              </div>
            </div>
          )}

        </main>
      </div>

      {/* Floating Add to Bag Notification Toast */}
      {cartToast && (
        <div className="fixed bottom-6 right-6 z-50 bg-[#11131A] border-2 border-[#00FF66] p-4 shadow-2xl flex items-center gap-4 animate-in fade-in slide-in-from-bottom-3 duration-200 max-w-md">
          <CheckCircle2 className="w-5 h-5 text-[#00FF66] shrink-0" />
          <div className="text-xs flex-1 min-w-0">
            <p className="font-bold text-white uppercase truncate">
              {cartToast.title} (Size {cartToast.size}) added!
            </p>
            <p className="text-[10px] text-[#A5AAB8] mt-0.5">
              100% Sky Cash will unlock on order delivery.
            </p>
          </div>
          <div className="flex items-center gap-2 shrink-0 pl-2 border-l border-white/[0.08]">
            <Link
              href="/cart"
              className="px-3 py-1.5 bg-[#0A0B0E] hover:bg-[rgba(255,255,255,0.08)] border border-white/[0.08] text-white text-[10px] font-bold uppercase transition-colors"
            >
              Bag
            </Link>
            <Link
              href="/checkout"
              className="px-3 py-1.5 bg-[#D9362B] hover:bg-[#B82B22] text-white text-[10px] font-bold uppercase transition-colors"
            >
              Checkout ↘
            </Link>
          </div>
        </div>
      )}
    </div>
  );
}

