source:
"use client";

import React, { useState, useEffect } from "react";
import {
  AlertCircle,
  Check,
  CheckCircle2,
  ChevronDown,
  Coins,
  Copy,
  Gift,
  Landmark,
  Loader2,
  Smartphone,
  X,
} from "lucide-react";
import type {
  WalletTransaction,
  WithdrawalRequest,
  BankAccount,
} from "@/data/rewardsEngine";
import type { StorefrontSnapshot, WithdrawalInput } from "@/lib/contracts";
import type { ShopOrder, ZeninNotification } from "@/lib/domain";
import { dateLabel, dateTimeLabel, formatRupees } from "@/lib/domain";
import { cashbackTotals } from "@/lib/vesting";
import { api } from "@/lib/client";

const UPI_RE = /^[\w.-]{2,256}@[a-zA-Z]{2,64}$/;
const BANK_ACCT_RE = /^\d{9,18}$/;
const IFSC_RE = /^[A-Za-z]{4}0[A-Za-z0-9]{6}$/;

const CARD = "rounded-2xl border border-white/[0.08] bg-[#11131A]";
const INPUT =
  "w-full rounded-xl border border-white/10 bg-[#0A0B0E] px-3.5 py-2.5 text-sm text-white placeholder-[#6B6F7A] focus:border-[#D9362B] focus:outline-none";
const PRIMARY_BTN =
  "inline-flex items-center justify-center gap-2 rounded-xl bg-[#D9362B] px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-[#B82B22] disabled:cursor-not-allowed disabled:opacity-40";
const SECONDARY_BTN =
  "inline-flex items-center justify-center gap-2 rounded-xl border border-white/10 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-white/[0.06] disabled:cursor-not-allowed disabled:opacity-40";

interface WalletPanelProps {
  snapshot: StorefrontSnapshot;
  notifications?: ZeninNotification[];
  onSubmitWithdrawal: (input: WithdrawalInput) => Promise<void>;
  onClaimCashback?: (options?: { orderId?: string; week?: number }) => Promise<void>;
  onAddBankAccount?: (input: {
    accountHolderName: string;
    accountNumber: string;
    ifscCode: string;
    bankName: string;
  }) => Promise<void>;
  onRemoveBankAccount?: (id: string) => Promise<void>;
  openWithdrawOnMount?: boolean;
  onViewAlerts?: () => void;
  view?: "wallet" | "withdrawals" | "all";
  onOpenWithdrawals?: () => void;
  initialWithdrawSource?: "referral" | "cashback";
}

function coins(value: number): string {
  return Math.round(value || 0).toLocaleString("en-IN");
}

function plainLedgerLine(description: string): string {
  return description
    .replace(
      /vesting coins released back after the payout desk rejected this request/i,
      "Coins from a cancelled payout returned to your wallet"
    )
    .replace(/vests 25% weekly for 4 weeks/i, "paid out weekly")
    .replace(/^cashback/i, "Cashback");
}

function payoutDestination(request: WithdrawalRequest): string {
  if (request.payoutMethod === "BANK") {
    const last4 = (request.bankAccount ?? "").slice(-4);
    return last4 ? `Bank account ••••${last4}` : "Bank account";
  }
  return request.upiId ? `UPI ${request.upiId}` : "UPI";
}

function withdrawalState(status: WithdrawalRequest["overallStatus"]): {
  label: string;
  dot: string;
  text: string;
} {
  if (status === "PAID" || status === "COMPLETED") {
    return { label: "Paid", dot: "bg-[#00FF66]", text: "text-[#00FF66]" };
  }
  if (status === "REJECTED" || status === "FAILED") {
    return { label: "Rejected", dot: "bg-rose-500", text: "text-rose-400" };
  }
  if (status === "REVERSED") {
    return { label: "Reversed", dot: "bg-orange-400", text: "text-orange-400" };
  }
  return { label: "Processing", dot: "bg-amber-400", text: "text-amber-300" };
}

function withdrawalReference(request: WithdrawalRequest): string | undefined {
  return (
    request.transactionRefNumber ||
    request.tranches.slice().reverse().find((t) => t.upiRef)?.upiRef
  );
}

function SectionHeading({ title, note }: { title: string; note?: string }) {
  return (
    <div className="mb-3">
      <h2 className="text-sm font-semibold text-white">{title}</h2>
      {note ? <p className="mt-0.5 text-xs text-[#8E929B]">{note}</p> : null}
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*                            Cashback release row                            */
/* -------------------------------------------------------------------------- */

function CashbackOrderRow({
  order,
  onClaimCashback,
  onError,
}: {
  order: ShopOrder;
  onClaimCashback?: (options?: { orderId?: string; week?: number }) => Promise<void>;
  onError: (message: string | null) => void;
}) {
  const totals = cashbackTotals(order.cashback);
  const [claiming, setClaiming] = useState<number | "all" | null>(null);

  const releasedPct =
    order.pointsEarned > 0
      ? Math.min(100, Math.round((totals.releasedPoints / order.pointsEarned) * 100))
      : 0;
  const productSummary = order.items.map((i) => i.title).join(", ") || "Streetwear order";
  const hasClaimable = totals.unlockedPoints > 0;
  const isUnverified = order.paymentStatus !== "PAID";
  const slices = order.cashback ?? [];

  const handleClaim = async (week?: number) => {
    if (!onClaimCashback || claiming !== null) return;
    setClaiming(week ?? "all");
    onError(null);
    try {
      await onClaimCashback({ orderId: order.id, week });
    } catch (err) {
      onError(err instanceof Error ? err.message : "Could not collect cashback");
    } finally {
      setClaiming(null);
    }
  };

  return (
    <div className={`${CARD} p-4 sm:p-5`}>
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="text-sm font-semibold text-white">Order #{order.orderNumber}</p>
          <p className="mt-0.5 truncate text-xs text-[#8E929B]">
            {productSummary} · {dateLabel(order.placedAt)}
          </p>
        </div>
        <div className="text-right">
          <p className="text-sm font-bold text-[#00FF66]">
            {coins(totals.releasedPoints)}{" "}
            <span className="font-normal text-[#8E929B]">/ {coins(order.pointsEarned)} coins</span>
          </p>
          <p className="text-[11px] text-[#8E929B]">collected</p>
        </div>
      </div>

      <div className="mt-3 h-1.5 w-full overflow-hidden rounded-full bg-[#0A0B0E]">
        <div
          className="h-full rounded-full bg-[#00FF66] transition-all duration-500"
          style={{ width: `${releasedPct}%` }}
        />
      </div>

      <div className="mt-3 flex flex-wrap items-center justify-between gap-2">
        <p className="text-xs text-[#8E929B]">
          {isUnverified
            ? "Cashback starts releasing once payment is verified."
            : hasClaimable
            ? `${coins(totals.unlockedPoints)} coins are ready to collect.`
            : totals.nextSlice
            ? `Next ${coins(totals.nextSlice.points)} coins release on ${totals.nextSlice.dueDate}.`
            : "All coins collected."}
        </p>

        {hasClaimable && onClaimCashback ? (
          <button
            type="button"
            onClick={() => void handleClaim()}
            disabled={claiming !== null}
            className="inline-flex items-center gap-1.5 rounded-lg bg-[#00FF66] px-3 py-1.5 text-xs font-semibold text-[#0A0B0E] transition-colors hover:bg-[#00FF66]/90 disabled:opacity-50"
          >
            {claiming === "all" ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Coins className="h-3.5 w-3.5" />
            )}
            Collect {coins(totals.unlockedPoints)} coins
          </button>
        ) : null}
      </div>

      {slices.length > 0 && (
        <details className="group mt-3 border-t border-white/[0.06] pt-3">
          <summary className="flex cursor-pointer list-none items-center justify-between text-xs text-[#8E929B] transition-colors hover:text-white [&::-webkit-details-marker]:hidden">
            <span>Daily release plan</span>
            <ChevronDown className="h-4 w-4 transition-transform group-open:rotate-180" />
          </summary>

          <div className="mt-2 max-h-64 space-y-1 overflow-y-auto pr-1">
            {slices.map((slice) => {
              const isReleased = slice.status === "RELEASED";
              const isUnlocked = slice.status === "UNLOCKED";
              const isVoid = slice.status === "VOID";
              return (
                <div
                  key={`${order.id}-day-${slice.week}`}
                  className="flex items-center justify-between gap-3 rounded-lg px-2 py-1.5 text-xs hover:bg-white/[0.03]"
                >
                  <div className="flex min-w-0 items-center gap-2">
                    <span className="w-12 shrink-0 text-[#8E929B]">Day {slice.week}</span>
                    <span className={isVoid ? "text-[#6B6F7A] line-through" : "text-[#F5F5F7]"}>
                      {coins(slice.points)} coins
                    </span>
                  </div>

                  {isReleased ? (
                    <span className="flex items-center gap-1 text-[11px] text-[#00FF66]">
                      <CheckCircle2 className="h-3.5 w-3.5" /> Collected
                    </span>
                  ) : isUnlocked ? (
                    onClaimCashback ? (
                      <button
                        type="button"
                        onClick={() => void handleClaim(slice.week)}
                        disabled={claiming !== null}
                        className="inline-flex items-center gap-1 rounded-md border border-[#00FF66]/40 px-2 py-0.5 text-[11px] font-semibold text-[#00FF66] transition-colors hover:bg-[#00FF66]/10 disabled:opacity-50"
                      >
                        {claiming === slice.week ? (
                          <Loader2 className="h-3 w-3 animate-spin" />
                        ) : null}
                        Collect
                      </button>
                    ) : (
                      <span className="text-[11px] text-amber-300">Ready</span>
                    )
                  ) : isVoid ? (
                    <span className="text-[11px] text-[#6B6F7A]">Void</span>
                  ) : (
                    <span className="text-[11px] text-[#6B6F7A]">{slice.dueDate}</span>
                  )}
                </div>
              );
            })}
          </div>
        </details>
      )}
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*                               Main wallet                                  */
/* -------------------------------------------------------------------------- */

export default function WalletPanel({
  snapshot,
  onSubmitWithdrawal,
  onClaimCashback,
  openWithdrawOnMount = false,
  view = "all",
  onOpenWithdrawals,
  initialWithdrawSource = "cashback",
}: WalletPanelProps) {
  const showWallet = view !== "withdrawals";
  const showWithdrawals = view !== "wallet";
  const forceWithdrawForm = view === "withdrawals";
  const customer = snapshot.customer;
  const rewardRules = snapshot.rewardRules;
  const orders = snapshot.orders;
  const transactions = snapshot.transactions;
  const withdrawals = snapshot.withdrawals;
  const bankAccounts: BankAccount[] = customer?.bankAccounts ?? [];
  const primaryBank = bankAccounts[0];

  const available = customer?.availablePoints ?? 0;
  const pointValue = rewardRules?.pointValueInRupees ?? 0.01;
  const minPoints = snapshot.minWithdrawalPoints ?? 500;
  const pendingCashbackCoins = customer?.pendingPoints ?? 0;

  const referralCashRupees =
    customer?.referralBalanceRupees ??
    snapshot.referrals
      .filter((r) => r.status === "PAID" || r.status === "APPROVED")
      .reduce((sum, r) => sum + (r.commissionEarned || 0), 0);
  const referralCoins = Math.round(referralCashRupees / pointValue);

  const verifiedPaidOrders = orders.filter(
    (o) => o.paymentStatus === "PAID" && o.status !== "CANCELLED"
  );
  const hasUnverifiedOrders = orders.some(
    (o) => o.paymentStatus !== "PAID" && o.status !== "CANCELLED" && o.pointsEarned > 0
  );
  const verifiedPaidPendingCoins = verifiedPaidOrders.reduce((sum, o) => {
    if (o.cashback && o.cashback.length > 0) {
      return (
        sum +
        o.cashback
          .filter((s) => s.status === "LOCKED" || s.status === "UNLOCKED")
          .reduce((acc, s) => acc + s.points, 0)
      );
    }
    return sum + (o.pointsEarned || 0);
  }, 0);
  const isAwaitingVerificationOnly =
    pendingCashbackCoins > 0 && verifiedPaidPendingCoins <= 0 && hasUnverifiedOrders;

  const todayKolkata = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Kolkata" });
  const hasClaimedDaily = customer?.lastDailyClaimDate === todayKolkata;

  const todayClaimableCoins = hasClaimedDaily
    ? 0
    : verifiedPaidOrders.reduce((sum, o) => {
        if (o.cashback && o.cashback.length > 0) {
          return (
            sum +
            o.cashback
              .filter((s) => s.status === "UNLOCKED")
              .reduce((acc, s) => acc + s.points, 0)
          );
        }
        return sum + Math.max(1, Math.floor((o.pointsEarned || 0) / 30));
      }, 0);

  const ordersWithCashback = orders.filter((o) => (o.cashback?.length ?? 0) > 0);

  const [withdrawOpen, setWithdrawOpen] = useState(openWithdrawOnMount);
  const [withdrawSource, setWithdrawSource] = useState<"REFERRAL_CASH" | "CASHBACK_POINTS">(
    initialWithdrawSource === "referral" ? "REFERRAL_CASH" : "CASHBACK_POINTS"
  );
  const [payoutMethod, setPayoutMethod] = useState<"UPI" | "BANK">("UPI");
  const [pointsInput, setPointsInput] = useState(() => String(available || ""));
  const [referralCoinsInput, setReferralCoinsInput] = useState(() =>
    String(referralCoins > 0 ? referralCoins : "")
  );
  const [submitting, setSubmitting] = useState(false);
  const [claimingAll, setClaimingAll] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const savedUpi = customer?.savedUpiId ?? "";
  const [upiId, setUpiId] = useState(savedUpi);
  const [isEditingUpi, setIsEditingUpi] = useState(false);
  const [newUpiValue, setNewUpiValue] = useState(savedUpi);
  const [savingUpi, setSavingUpi] = useState(false);
  const [upiActionError, setUpiActionError] = useState<string | null>(null);

  const [bankAccount, setBankAccount] = useState(primaryBank?.accountNumber ?? "");
  const [bankIfsc, setBankIfsc] = useState(primaryBank?.ifscCode ?? "");
  const [isEditingBank, setIsEditingBank] = useState(false);
  const [newHolderName, setNewHolderName] = useState(
    primaryBank?.accountHolderName || customer?.name || ""
  );
  const [newBankName, setNewBankName] = useState(primaryBank?.bankName || "");
  const [newAccountNum, setNewAccountNum] = useState("");
  const [confirmAccountNum, setConfirmAccountNum] = useState("");
  const [newIfsc, setNewIfsc] = useState(primaryBank?.ifscCode || "");
  const [savingBank, setSavingBank] = useState(false);
  const [bankActionError, setBankActionError] = useState<string | null>(null);

  const [copiedRef, setCopiedRef] = useState<string | null>(null);

  useEffect(() => {
    if (customer?.savedUpiId) {
      setUpiId(customer.savedUpiId);
      setNewUpiValue(customer.savedUpiId);
    }
  }, [customer?.savedUpiId]);

  useEffect(() => {
    if (primaryBank) {
      setBankAccount(primaryBank.accountNumber);
      setBankIfsc(primaryBank.ifscCode);
      setNewHolderName(primaryBank.accountHolderName);
      setNewBankName(primaryBank.bankName);
      setNewIfsc(primaryBank.ifscCode);
    }
  }, [primaryBank]);

  const points = Math.max(0, Math.floor(Number(pointsInput) || 0));
  const withdrawReferralCoins = Math.max(0, parseInt(referralCoinsInput, 10) || 0);
  const minReferralCoins = 1000;

  const belowMinReferral = withdrawReferralCoins < minReferralCoins;
  const aboveAvailReferral = withdrawReferralCoins > referralCoins;
  const belowMinCoins = points < minPoints;
  const aboveAvailCoins = points > available;

  const upiValid = UPI_RE.test(upiId.trim());
  const bankValid =
    BANK_ACCT_RE.test(bankAccount.replace(/\s/g, "")) &&
    IFSC_RE.test(bankIfsc.trim().toUpperCase());
  const payoutValid = payoutMethod === "UPI" ? upiValid : bankValid;

  const canSubmit =
    withdrawSource === "REFERRAL_CASH"
      ? withdrawReferralCoins > 0 &&
        !belowMinReferral &&
        !aboveAvailReferral &&
        payoutValid &&
        !submitting
      : points > 0 && !belowMinCoins && !aboveAvailCoins && payoutValid && !submitting;

  const openWithdraw = (source: "REFERRAL_CASH" | "CASHBACK_POINTS") => {
    setWithdrawSource(source);
    if (source === "REFERRAL_CASH") {
      setReferralCoinsInput(String(referralCoins > 0 ? referralCoins : ""));
    } else {
      setPointsInput(String(available || ""));
    }
    setFormError(null);
    setWithdrawOpen(true);
  };

  const handleDailyClaim = async () => {
    if (
      !onClaimCashback ||
      claimingAll ||
      hasClaimedDaily ||
      todayClaimableCoins <= 0 ||
      pendingCashbackCoins <= 0 ||
      isAwaitingVerificationOnly
    ) {
      return;
    }
    setClaimingAll(true);
    setSuccessMsg(null);
    setFormError(null);
    try {
      await onClaimCashback();
      setSuccessMsg(`Collected ${coins(todayClaimableCoins)} coins into your wallet.`);
    } catch (err) {
      setFormError(err instanceof Error ? err.message : "Failed to collect cashback");
    } finally {
      setClaimingAll(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canSubmit) return;
    setSubmitting(true);
    setFormError(null);
    setSuccessMsg(null);
    try {
      const cleanBankAcct = bankAccount.replace(/\s/g, "");
      const cleanIfsc = bankIfsc.trim().toUpperCase();
      const effectiveMethod: "UPI" | "BANK" =
        payoutMethod === "BANK" ||
        (BANK_ACCT_RE.test(cleanBankAcct) && IFSC_RE.test(cleanIfsc) && !upiId.trim())
          ? "BANK"
          : "UPI";

      const amountCoins =
        withdrawSource === "REFERRAL_CASH" ? withdrawReferralCoins : points;

      await onSubmitWithdrawal({
        points: amountCoins,
        sourceType: withdrawSource,
        payoutMethod: effectiveMethod,
        ...(effectiveMethod === "UPI" ? { upiId: upiId.trim() } : {}),
        ...(effectiveMethod === "BANK"
          ? { bankAccount: cleanBankAcct, bankIfsc: cleanIfsc }
          : {}),
      });

      setWithdrawOpen(false);
      setSuccessMsg(
        `Withdrawal request for ${coins(amountCoins)} coins submitted. Admin will transfer to ${
          effectiveMethod === "BANK"
            ? `bank account ending ••••${cleanBankAcct.slice(-4)}`
            : upiId
        } after review.`
      );

      if (forceWithdrawForm) {
        setPointsInput("");
        setReferralCoinsInput("");
      } else if (withdrawSource === "REFERRAL_CASH") {
        setReferralCoinsInput(String(Math.max(0, referralCoins - amountCoins)));
      } else {
        setPointsInput(available > 0 ? String(Math.max(0, available - amountCoins)) : "");
      }
    } catch (err) {
      setFormError(err instanceof Error ? err.message : "Withdrawal failed. Try again.");
    } finally {
      setSubmitting(false);
    }
  };

  const handleSaveUpi = async (e: React.FormEvent) => {
    e.preventDefault();
    setUpiActionError(null);
    const clean = newUpiValue.trim().toLowerCase();
    if (!UPI_RE.test(clean)) {
      setUpiActionError("Enter a valid UPI ID like mobile@upi or name@bank");
      return;
    }
    setSavingUpi(true);
    try {
      const res = await api.updateUpi(clean);
      setIsEditingUpi(false);
      setUpiId(clean);
      setSuccessMsg(
        res.pendingReview
          ? "UPI change submitted for admin review."
          : "UPI ID linked to your profile."
      );
    } catch (err: any) {
      setUpiActionError(err?.message || "Failed to update UPI ID");
    } finally {
      setSavingUpi(false);
    }
  };

  const handleSaveBankAccount = async (e: React.FormEvent) => {
    e.preventDefault();
    setBankActionError(null);
    if (!newHolderName.trim()) {
      setBankActionError("Account holder name is required.");
      return;
    }
    if (!newBankName.trim()) {
      setBankActionError("Bank name is required.");
      return;
    }
    const cleanNum = newAccountNum.replace(/\s/g, "");
    if (!BANK_ACCT_RE.test(cleanNum)) {
      setBankActionError("Enter a valid 9-18 digit account number.");
      return;
    }
    if (cleanNum !== confirmAccountNum.replace(/\s/g, "")) {
      setBankActionError("Account numbers do not match.");
      return;
    }
    if (!IFSC_RE.test(newIfsc.trim().toUpperCase())) {
      setBankActionError("Enter a valid 11-character IFSC code (e.g. INDB0000476).");
      return;
    }

    setSavingBank(true);
    try {
      const res = await api.addBankAccount({
        accountHolderName: newHolderName.trim(),
        accountNumber: cleanNum,
        bankName: newBankName.trim(),
        ifscCode: newIfsc.trim().toUpperCase(),
      });
      setIsEditingBank(false);
      setBankAccount(cleanNum);
      setBankIfsc(newIfsc.trim().toUpperCase());
      setNewAccountNum("");
      setConfirmAccountNum("");
      setSuccessMsg(
        res.pendingReview
          ? "Bank account change submitted for admin review."
          : "Bank account linked to your profile."
      );
    } catch (err: any) {
      setBankActionError(err?.message || "Failed to save bank account");
    } finally {
      setSavingBank(false);
    }
  };

  const copyReference = (reference: string) => {
    void navigator.clipboard.writeText(reference);
    setCopiedRef(reference);
    setTimeout(() => setCopiedRef(null), 2000);
  };

  const amountCoins = withdrawSource === "REFERRAL_CASH" ? withdrawReferralCoins : points;
  const maxWithdrawCoins = withdrawSource === "REFERRAL_CASH" ? referralCoins : available;
  const showWithdrawForm = forceWithdrawForm || (view === "all" && withdrawOpen);
  const amountError =
    withdrawSource === "REFERRAL_CASH"
      ? belowMinReferral && withdrawReferralCoins > 0
        ? `Minimum referral withdrawal is ${coins(minReferralCoins)} coins.`
        : aboveAvailReferral
        ? `You have ${coins(referralCoins)} referral coins available.`
        : null
      : belowMinCoins && points > 0
      ? `Minimum withdrawal is ${coins(minPoints)} coins.`
      : aboveAvailCoins
      ? `You have ${coins(available)} coins available.`
      : null;

  return (
    <div className="mx-auto max-w-5xl space-y-6 text-[#F5F5F7]">
      {successMsg && (
        <div className="flex items-start gap-2.5 rounded-xl border border-[#00FF66]/30 bg-[#00FF66]/[0.08] p-3.5 text-sm text-[#00FF66]">
          <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
          <p className="flex-1">{successMsg}</p>
          <button
            type="button"
            onClick={() => setSuccessMsg(null)}
            className="text-[#00FF66]/70 transition-colors hover:text-[#00FF66]"
            aria-label="Dismiss"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {formError && (
        <div className="flex items-start gap-2.5 rounded-xl border border-rose-500/30 bg-rose-500/[0.08] p-3.5 text-sm text-rose-300">
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
          <p className="flex-1">{formError}</p>
          <button
            type="button"
            onClick={() => setFormError(null)}
            className="text-rose-300/70 transition-colors hover:text-rose-200"
            aria-label="Dismiss"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* Balance */}
      {showWallet && (
        <section className={`${CARD} p-4 sm:p-5`}>
          <div className="flex items-start justify-between gap-3">
            <div>
              <p className="text-xs font-medium uppercase tracking-wider text-[#8E929B]">
                Live wallet
              </p>
              <p className="mt-1.5 text-4xl font-bold tracking-tight text-white">
                {coins(available)}{" "}
                <span className="text-base font-medium text-[#8E929B]">coins</span>
              </p>
            </div>
            <span className="inline-flex shrink-0 items-center gap-1.5 rounded-full border border-[#00FF66]/25 bg-[#00FF66]/[0.08] px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-[#00FF66]">
              <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-[#00FF66]" />
              Live
            </span>
          </div>

          <div className="mt-4 grid grid-cols-2 gap-2 sm:max-w-md">
            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <p className="text-[10px] font-medium uppercase tracking-wider text-[#6B6F7A]">
                Referral coins
              </p>
              <p className="mt-0.5 text-base font-bold tracking-tight text-[#00FF66]">
                {coins(referralCoins)}
              </p>
            </div>
            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <p className="text-[10px] font-medium uppercase tracking-wider text-[#6B6F7A]">
                Pending coins
              </p>
              <p
                className={`mt-0.5 text-base font-bold tracking-tight ${
                  pendingCashbackCoins > 0 ? "text-amber-300" : "text-white"
                }`}
              >
                {coins(pendingCashbackCoins)}
              </p>
            </div>
          </div>

          <div className="mt-4 flex flex-wrap items-center gap-2.5">
            <button
              type="button"
              onClick={() => {
                if (onOpenWithdrawals) {
                  onOpenWithdrawals();
                  return;
                }
                openWithdraw("CASHBACK_POINTS");
              }}
              disabled={!onOpenWithdrawals && available < minPoints && referralCoins <= 0}
              className={PRIMARY_BTN}
            >
              Withdraw coins
            </button>

            {onClaimCashback && todayClaimableCoins > 0 && !hasClaimedDaily && (
              <button
                type="button"
                onClick={() => void handleDailyClaim()}
                disabled={claimingAll || isAwaitingVerificationOnly}
                className={SECONDARY_BTN}
              >
                {claimingAll ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Coins className="h-4 w-4 text-[#00FF66]" />
                )}
                Collect {coins(todayClaimableCoins)} coins
              </button>
            )}

            {hasClaimedDaily && todayClaimableCoins === 0 && ordersWithCashback.length > 0 && (
              <span className="inline-flex items-center gap-1.5 text-xs text-[#8E929B]">
                <CheckCircle2 className="h-3.5 w-3.5 text-[#00FF66]" />
                Collected for today
              </span>
            )}
          </div>

          <p className="mt-3 text-[11px] text-[#6B6F7A]">
            Minimum {coins(minPoints)} coins.
          </p>
        </section>
      )}

      {/* Live balances */}
      {forceWithdrawForm && (
        <section className={`${CARD} overflow-hidden`}>
          <div className="grid grid-cols-3 divide-x divide-white/[0.06]">
            <div className="min-w-0 p-4">
              <p className="text-[10px] font-medium uppercase tracking-wider text-[#8E929B]">
                Wallet coins
              </p>
              <p className="mt-1 truncate text-lg font-bold tracking-tight text-white sm:text-xl">
                {coins(available)}
              </p>
            </div>
            <div className="min-w-0 p-4">
              <p className="text-[10px] font-medium uppercase tracking-wider text-[#8E929B]">
                Referral coins
              </p>
              <p className="mt-1 truncate text-lg font-bold tracking-tight text-[#00FF66] sm:text-xl">
                {coins(referralCoins)}
              </p>
            </div>
            <div className="min-w-0 p-4">
              <p className="text-[10px] font-medium uppercase tracking-wider text-[#8E929B]">
                Pending coins
              </p>
              <p
                className={`mt-1 truncate text-lg font-bold tracking-tight sm:text-xl ${
                  pendingCashbackCoins > 0 ? "text-amber-300" : "text-white"
                }`}
              >
                {coins(pendingCashbackCoins)}
              </p>
            </div>
          </div>
          <p className="border-t border-white/[0.06] px-4 py-2.5 text-[11px] text-[#6B6F7A]">
            Pending coins unlock weekly and move into your wallet.
          </p>
        </section>
      )}

      {/* Withdraw form */}
      {showWithdrawForm && (
        <section className={`${CARD} p-4 sm:p-5`}>
          <div className="mb-5 flex items-start justify-between gap-3">
            <div>
              <h2 className="text-sm font-semibold text-white">Withdraw coins</h2>
              <p className="mt-0.5 text-xs text-[#8E929B]">
                Minimum{" "}
                {coins(withdrawSource === "REFERRAL_CASH" ? minReferralCoins : minPoints)} coins
              </p>
            </div>
            {!forceWithdrawForm && (
              <button
                type="button"
                onClick={() => {
                  setWithdrawOpen(false);
                  setFormError(null);
                }}
                className="rounded-lg p-1.5 text-[#8E929B] transition-colors hover:bg-white/[0.06] hover:text-white"
                aria-label="Close"
              >
                <X className="h-4 w-4" />
              </button>
            )}
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="grid grid-cols-2 gap-2">
              {(
                [
                  { value: "CASHBACK_POINTS", label: "Wallet coins", icon: Coins },
                  { value: "REFERRAL_CASH", label: "Referral coins", icon: Gift },
                ] as const
              ).map((source) => {
                const active = withdrawSource === source.value;
                const Icon = source.icon;
                return (
                  <button
                    key={source.value}
                    type="button"
                    onClick={() => {
                      setWithdrawSource(source.value);
                      if (source.value === "REFERRAL_CASH") {
                        setReferralCoinsInput(String(referralCoins > 0 ? referralCoins : ""));
                      } else {
                        setPointsInput(String(available || ""));
                      }
                      setFormError(null);
                    }}
                    className={`flex items-center gap-2.5 rounded-xl border px-3 py-2.5 text-left text-xs font-semibold transition-colors ${
                      active
                        ? "border-[#D9362B]/50 bg-[#D9362B]/[0.08] text-white"
                        : "border-white/[0.08] text-[#8E929B] hover:border-white/15 hover:text-white"
                    }`}
                  >
                    <Icon
                      className={`h-4 w-4 shrink-0 ${active ? "text-[#D9362B]" : "text-[#8E929B]"}`}
                    />
                    <span className="flex-1 truncate">{source.label}</span>
                    {active && <Check className="h-3.5 w-3.5 shrink-0 text-[#D9362B]" />}
                  </button>
                );
              })}
            </div>

            <div>
              <label
                htmlFor="withdraw-amount"
                className="mb-2 block text-xs font-medium text-[#8E929B]"
              >
                Amount
              </label>
              <div className="relative">
                <input
                  id="withdraw-amount"
                  type="number"
                  inputMode="numeric"
                  min={0}
                  step={1}
                  value={withdrawSource === "REFERRAL_CASH" ? referralCoinsInput : pointsInput}
                  onChange={(e) =>
                    withdrawSource === "REFERRAL_CASH"
                      ? setReferralCoinsInput(e.target.value)
