function ActivityRow({
  tx,
  pointValue,
}: {
  tx: WalletTransaction;
  pointValue: number;
}) {
  const displayCoins =
    tx.type === "REFERRAL_COMMISSION" && tx.points === 0
      ? Math.round((tx.rupeeValue || 0) / pointValue)
      : tx.points;
  const positive = displayCoins > 0;

  return (
    <div className="flex items-start justify-between gap-3 p-4">
      <div className="min-w-0">
        <p className="text-sm text-[#F5F5F7]">{plainLedgerLine(tx.description)}</p>
        <p className="mt-0.5 text-xs text-[#8E929B]">
          {tx.date} · {tx.status.toLowerCase()}
        </p>
      </div>
      <p
        className={`shrink-0 text-sm font-semibold ${
          positive ? "text-[#00FF66]" : "text-rose-400"
        }`}
      >
        {positive ? "+" : ""}
        {coins(displayCoins)} coins
      </p>
    </div>
  );
}

