      (state.customers.reduce((sum, c) => sum + c.availablePoints + c.pendingPoints, 0) *
        state.rewardRules.pointValueInRupees).toFixed(2)
    ),
    paidOutRupees: Number(
      state.withdrawals
        .reduce((sum, w) => sum + vestingTotals(w).paidRupees, 0)
        .toFixed(2)
    ),
    pendingPayableRupees: Number(
      state.withdrawals
        .reduce((sum, w) => sum + vestingTotals(w).payableNowRupees, 0)
