          pendingPoints: 0,
          lifetimeEarnedPoints: 0,
          tier: "Silver",
          addresses: [],
          bankAccounts: [],
        };
        state.customers.push(customer);
      }
    }

    state.activeCustomerId = customer.id;
    recordAudit(state, customer.name, "CUSTOMER_SIGNIN", `Session started for ${customer.phone}`);
